buy_code:
매수 = True

if 데이터길이 < {min_len}:
    매수 = False
elif {b1_start} <= 시분초 < {b1_end}:
    # 밴드1: 개장 09:00~10:00, 중형 시총, 분당거래대금 재가속 + 누적 매수우위 지속
    if {b1_cap_lo} <= 시가총액 < {b1_cap_hi}:
        if not (
            {b1_rate_min} <= 등락율 <= {b1_rate_max}
            and 당일거래대금 >= {b1_day_money_min}
            and 분당거래대금 >= {b1_min_money_min}
            and 분당거래대금 >= 분당거래대금평균({b1_money_avg_win}, 1) * {b1_money_burst}
            and 누적분당매수수량({b1_cum_win}) >= 누적분당매도수량({b1_cum_win}) * {b1_cum_buy_ratio}
            and 분당매수수량 >= 분당매도수량 * {b1_now_buy_ratio}
            and 현재가 >= 이동평균({b1_price_ma_win}, 1) * {b1_price_ma_mult}
        ):
            매수 = False
    else:
        매수 = False
elif {b2_start} <= 시분초 < {b2_end}:
    # 밴드2: 오후 13:00~15:00, 다른 시총군, 직전 분봉고가 돌파 대용 MA 상향돌파 + 더 강한 재가속
    if {b2_cap_lo} <= 시가총액 < {b2_cap_hi}:
        if not (
            {b2_rate_min} <= 등락율 <= {b2_rate_max}
            and 당일거래대금 >= {b2_day_money_min}
            and 분당거래대금 >= {b2_min_money_min}
            and 분당거래대금 >= 분당거래대금평균({b2_money_avg_win}, 1) * {b2_money_burst}
            and 누적분당매수수량({b2_cum_win}) >= 누적분당매도수량({b2_cum_win}) * {b2_cum_buy_ratio}
            and 분당매수수량 >= 분당매도수량 * {b2_now_buy_ratio}
            and 현재가 >= 이동평균({b2_price_ma_win}, 1) * {b2_price_ma_mult}
        ):
            매수 = False
    else:
        매수 = False
else:
    매수 = False

if 매수:
    self.Buy()

sell_code:
매도 = False

if 수익률 >= {take_profit}:
    매도 = True
elif 수익률 <= -{stop_loss}:
    매도 = True
elif 최고수익률 >= {trail_start} and 수익률 <= 최고수익률 - {trail_gap}:
    매도 = True
elif 보유시간 >= {max_hold_sec}:
    매도 = True

if 매도:
    self.Sell()
